SELECT
    $__timeInterval(ts) AS time,
    event_type,
    count() AS changes
FROM resource_states FINAL
WHERE cluster_id = ${cluster:sqlstring}
  AND kind = ${kind:sqlstring}
  AND namespace = ${namespace:sqlstring}
  AND name = ${name:sqlstring}
  AND $__timeFilter(ts)
GROUP BY time, event_type
ORDER BY time

SELECT
    actor,
    count() AS rows_touched
FROM
(
    SELECT arrayJoin(actors) AS actor
    FROM resource_states FINAL
    WHERE cluster_id = ${cluster:sqlstring}
      AND kind = ${kind:sqlstring}
      AND namespace = ${namespace:sqlstring}
      AND name = ${name:sqlstring}
      AND $__timeFilter(ts)
)
GROUP BY actor
ORDER BY rows_touched DESC
LIMIT 20

SELECT
    argMax(event_type, ts)       AS last_event,
    max(ts)                      AS last_seen,
    argMax(uid, ts)              AS current_uid,
    argMax(resource_version, ts) AS resource_version,
    argMax(sha256, ts)           AS sha256,
    count()                      AS rows_recorded,
    uniqExact(uid)               AS incarnations
FROM resource_states
WHERE cluster_id = ${cluster:sqlstring}
  AND kind = ${kind:sqlstring}
  AND namespace = ${namespace:sqlstring}
  AND name = ${name:sqlstring}
